INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (19, 'PMBOK significa:', 'opcion_multiple', '["Project Management Book of Knowledge", "Project Management Body of Knowledge", "Program Management Body", "Project Method Book"]', 'Project Management Body of Knowledge', 'Guía de los Fundamentos para la Dirección de Proyectos del PMI.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (19, 'Los 5 grupos de procesos son:', 'opcion_multiple', '["Inicio, Planificación, Ejecución, Monitoreo, Cierre", "Plan, Do, Check, Act", "Análisis, Diseño, Implementación", "Solo 3 procesos"]', 'Inicio, Planificación, Ejecución, Monitoreo, Cierre', 'Según PMBOK: Inicio, Planificación, Ejecución, Monitoreo y Control, Cierre.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (19, 'Un stakeholder es:', 'opcion_multiple', '["Solo el cliente", "Cualquier persona afectada por el proyecto", "Solo el gerente", "Solo el equipo"]', 'Cualquier persona afectada por el proyecto', 'Parte interesada o interesadas en el proyecto.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (19, 'El triple constraint incluye:', 'opcion_multiple', '["Tiempo, Costo, Alcance", "Calidad, Riesgo, Recursos", "Solo tiempo y costo", "Solo alcance"]', 'Tiempo, Costo, Alcance', 'Las tres restricciones principales del proyecto.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (19, 'Un entregable es:', 'opcion_multiple', '["Solo un documento", "Producto o resultado único y verificable", "Solo código", "Solo informe"]', 'Producto o resultado único y verificable', 'Cualquier producto, resultado o capacidad única y verificable.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (19, 'El acta de constitución del proyecto:', 'opcion_multiple', '["Autoriza formalmente el proyecto", "Es opcional", "Solo es un borrador", "No existe"]', 'Autoriza formalmente el proyecto', 'Documento que autoriza formalmente el inicio del proyecto.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (19, 'La EDT (WBS) es:', 'opcion_multiple', '["Estructura de Desglose de Trabajo", "Solo un cronograma", "Solo un presupuesto", "Solo un riesgo"]', 'Estructura de Desglose de Trabajo', 'Descomposición jerárquica del trabajo del proyecto.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (19, 'Un riesgo en proyectos es:', 'opcion_multiple', '["Siempre negativo", "Evento incierto que puede afectar objetivos", "Siempre positivo", "No existe"]', 'Evento incierto que puede afectar objetivos', 'Puede ser amenaza u oportunidad.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (19, 'La ruta crítica es:', 'opcion_multiple', '["La más corta", "La secuencia más larga que determina duración", "Opcional", "Sin importancia"]', 'La secuencia más larga que determina duración', 'Determina la duración mínima del proyecto.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (19, 'El valor ganado (EV) mide:', 'opcion_multiple', '["Solo costo", "Trabajo completado en términos de presupuesto", "Solo tiempo", "Solo calidad"]', 'Trabajo completado en términos de presupuesto', 'Valor del trabajo realmente completado.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (19, 'Scrum es:', 'opcion_multiple', '["Una metodología ágil", "Un lenguaje de programación", "Una base de datos", "Un sistema operativo"]', 'Una metodología ágil', 'Framework ágil para gestión de proyectos complejos.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (19, 'Un Sprint en Scrum dura:', 'opcion_multiple', '["1 día", "2-4 semanas típicamente", "6 meses", "1 año"]', '2-4 semanas típicamente', 'Iteración time-boxed de 2-4 semanas.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (19, 'El Product Owner es:', 'opcion_multiple', '["El desarrollador", "Responsable del backlog y valor del producto", "El tester", "El cliente final"]', 'Responsable del backlog y valor del producto', 'Representa a los stakeholders y maximiza el valor.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (19, 'El Scrum Master es:', 'opcion_multiple', '["El jefe del equipo", "Facilitador que elimina impedimentos", "El cliente", "El Product Owner"]', 'Facilitador que elimina impedimentos', 'Sirve al equipo eliminando obstáculos.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (19, 'El Daily Scrum es:', 'opcion_multiple', '["Reunión semanal", "Reunión diaria de 15 minutos", "Reunión mensual", "No existe"]', 'Reunión diaria de 15 minutos', 'Stand-up meeting diario de sincronización.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (19, 'El Product Backlog es:', 'opcion_multiple', '["Lista de bugs", "Lista priorizada de requisitos", "Solo documentación", "Solo código"]', 'Lista priorizada de requisitos', 'Lista dinámica de todo lo necesario en el producto.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (19, 'User Stories describen:', 'opcion_multiple', '["Solo código", "Requisitos desde perspectiva del usuario", "Solo tests", "Solo diseño"]', 'Requisitos desde perspectiva del usuario', 'Formato: ''Como [rol], quiero [característica] para [beneficio]''.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (19, 'Kanban se enfoca en:', 'opcion_multiple', '["Sprints fijos", "Flujo continuo y visualización", "Solo documentación", "Solo reuniones"]', 'Flujo continuo y visualización', 'Sistema visual para gestionar trabajo en progreso.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (19, 'WIP significa:', 'opcion_multiple', '["Work In Progress", "Work Is Perfect", "Work In Plan", "Work Is Planned"]', 'Work In Progress', 'Trabajo en progreso, limitado en Kanban.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (19, 'El velocity en Scrum mide:', 'opcion_multiple', '["Velocidad de internet", "Puntos completados por sprint", "Solo tiempo", "Solo costo"]', 'Puntos completados por sprint', 'Cantidad de trabajo completado en un sprint.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (19, 'Un diagrama de Gantt muestra:', 'opcion_multiple', '["Solo texto", "Cronograma visual del proyecto", "Solo costos", "Solo riesgos"]', 'Cronograma visual del proyecto', 'Barras horizontales que representan tareas en el tiempo.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (19, 'Trello es:', 'opcion_multiple', '["Base de datos", "Herramienta de gestión tipo Kanban", "Lenguaje de programación", "Sistema operativo"]', 'Herramienta de gestión tipo Kanban', 'Herramienta visual de gestión de proyectos.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (19, 'Jira se usa principalmente para:', 'opcion_multiple', '["Diseño gráfico", "Gestión de proyectos de software", "Solo email", "Solo documentos"]', 'Gestión de proyectos de software', 'Herramienta de seguimiento de issues y proyectos ágiles.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (19, 'Un milestone es:', 'opcion_multiple', '["Una tarea larga", "Hito o punto de referencia importante", "Un riesgo", "Un costo"]', 'Hito o punto de referencia importante', 'Evento significativo con duración cero.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (19, 'La matriz RACI define:', 'opcion_multiple', '["Solo costos", "Roles y responsabilidades", "Solo tiempos", "Solo riesgos"]', 'Roles y responsabilidades', 'Responsible, Accountable, Consulted, Informed.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (19, 'Un KPI es:', 'opcion_multiple', '["Solo un número", "Indicador clave de desempeño", "Solo texto", "Solo imagen"]', 'Indicador clave de desempeño', 'Métrica para evaluar éxito del proyecto.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (19, 'La línea base (baseline) es:', 'opcion_multiple', '["Versión original del plan", "Solo el cronograma", "Solo el presupuesto", "No existe"]', 'Versión original del plan', 'Plan aprobado contra el cual se mide el desempeño.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (19, 'Un change request es:', 'opcion_multiple', '["Solo un email", "Solicitud formal de cambio", "Solo verbal", "No existe"]', 'Solicitud formal de cambio', 'Propuesta formal para modificar algún aspecto del proyecto.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (19, 'La gestión de la calidad incluye:', 'opcion_multiple', '["Solo testing", "Aseguramiento y control de calidad", "Solo documentación", "Solo reuniones"]', 'Aseguramiento y control de calidad', 'QA (procesos) y QC (productos/resultados).', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (19, 'Un lesson learned es:', 'opcion_multiple', '["Solo error", "Aprendizaje documentado del proyecto", "Solo éxito", "No se documenta"]', 'Aprendizaje documentado del proyecto', 'Conocimiento ganado para mejorar proyectos futuros.', 'intermedio');
