INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (20, 'La comunicación asertiva es:', 'opcion_multiple', '["Agresiva", "Clara, directa y respetuosa", "Pasiva", "Indirecta"]', 'Clara, directa y respetuosa', 'Expresar pensamientos y sentimientos de manera clara sin violar derechos de otros.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (20, 'La escucha activa implica:', 'opcion_multiple', '["Solo oír", "Prestar atención completa y comprender", "Interrumpir", "Ignorar"]', 'Prestar atención completa y comprender', 'Escuchar con atención, comprender y responder adecuadamente.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (20, 'El lenguaje no verbal incluye:', 'opcion_multiple', '["Solo palabras", "Gestos, postura, expresiones", "Solo email", "Solo teléfono"]', 'Gestos, postura, expresiones', 'Comunicación sin palabras: gestos, postura, contacto visual.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (20, 'La retroalimentación constructiva debe ser:', 'opcion_multiple', '["Crítica destructiva", "Específica, oportuna y respetuosa", "General", "Tardía"]', 'Específica, oportuna y respetuosa', 'Feedback específico, en el momento adecuado y de forma respetuosa.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (20, 'Una barrera de comunicación es:', 'opcion_multiple', '["Claridad", "Ruido o interferencia", "Escucha activa", "Empatía"]', 'Ruido o interferencia', 'Cualquier cosa que impida la comunicación efectiva.', 'intermedio');
