INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (20, 'Un buen líder debe:', 'opcion_multiple', '["Solo mandar", "Ejemplificar y servir al equipo", "Solo criticar", "Ignorar problemas"]', 'Ejemplificar y servir al equipo', 'Liderar con el ejemplo y apoyar el desarrollo del equipo.', 'intermedio');
